<script setup>
import { Star, Flag, Trash2, Clock3, GripVertical, ChevronDown, Check } from 'lucide-vue-next'
import { ref, onMounted, onUnmounted } from 'vue'
import { formatRelativeTime,formatDateTime } from '../utils/timeFormat'
defineProps({task:{type:Object,required:true}})
const emit=defineEmits(['toggle','remove','move'])
const menu=ref(false), moveWrap=ref(null)
function outside(e){ if(!moveWrap.value?.contains(e.target))menu.value=false }
onMounted(()=>document.addEventListener('pointerdown',outside))
onUnmounted(()=>document.removeEventListener('pointerdown',outside))
function start(e,task){e.dataTransfer.setData('text/plain',task.id);e.dataTransfer.effectAllowed='move'}
</script>
<template><article class="task-card" :class="{urgent:task.urgent,completed:task.columnId==='done'}" draggable="true" @dragstart="start($event,task)"><div class="card-top"><span class="tag" :class="{'tag-work':task.category==='工作','tag-life':task.category==='生活','tag-idea':task.category==='灵感'}">{{task.category||'未分类'}}</span><div class="card-flags"><span v-if="task.urgent" class="urgent-label">优先</span><button class="small-icon star-btn" :class="{active:task.starred}" :aria-label="task.starred?'取消星标':'星标任务'" :aria-pressed="task.starred" @click="emit('toggle',task.id,'starred')"><Star :size="16" :fill="task.starred?'currentColor':'none'"/></button><GripVertical :size="15" class="grip"/></div></div><h3><Check v-if="task.columnId==='done'" :size="17"/>{{task.title}}</h3><p v-if="task.description">{{task.description}}</p><footer><span class="time" :title="formatDateTime(task.createdAt)"><Clock3 :size="12"/>{{formatRelativeTime(task.createdAt)}}</span><div class="card-tools"><button class="small-icon" :class="{flagged:task.urgent}" :aria-label="task.urgent?'取消紧急':'标记紧急'" @click="emit('toggle',task.id,'urgent')"><Flag :size="14"/></button><button class="small-icon delete" aria-label="删除任务" @click="emit('remove',task.id)"><Trash2 :size="14"/></button><div ref="moveWrap" class="move-wrap" @keydown.esc="menu=false"><button class="small-icon" aria-label="更改任务状态" :aria-expanded="menu" @click="menu=!menu"><ChevronDown :size="15"/></button><div v-if="menu" class="move-menu" @mousedown.prevent><button v-for="col in [{id:'todo',title:'待办'},{id:'doing',title:'进行中'},{id:'done',title:'已完成'}]" :key="col.id" :disabled="task.columnId===col.id" @click="emit('move',task.id,col.id);menu=false">{{col.title}}</button></div></div></div></footer></article></template>
<style scoped>.task-card{position:relative;padding:19px 20px 13px;background:var(--card);border:1px solid var(--card-border);border-radius:14px;box-shadow:0 3px 8px #20254203;cursor:grab;transition:box-shadow .2s,transform .2s}.task-card:focus-within{z-index:20}.task-card:hover{z-index:20;transform:translateY(-2px);box-shadow:var(--shadow)}.task-card:active{cursor:grabbing}.urgent{border-left:3px solid #e99588;padding-left:18px}.card-top,.card-flags,footer,.card-tools{display:flex;align-items:center}.card-top{justify-content:space-between}.card-flags{gap:8px}.tag{font-size:10px;line-height:1.4;padding:4px 8px;border-radius:5px;background:var(--tag);color:var(--accent)}.tag-work{background:#edeafa;color:#8970c2}.tag-life{background:#f8eedd;color:#b18a47}.tag-idea{background:#e9f0fb;color:#6a8eb3}.urgent-label{font-size:10px;color:#cc8276}.grip{color:var(--faint)}h3{display:flex;gap:7px;align-items:center;font-size:14px;font-weight:600;line-height:1.6;margin:14px 0 7px}h3 svg{flex-shrink:0;color:#69aa93}p{font-size:12px;line-height:1.9;color:var(--muted);white-space:pre-wrap;overflow-wrap:anywhere;margin:0 0 19px}footer{padding-top:11px;margin-top:14px;border-top:1px solid var(--line);justify-content:space-between}.time{display:flex;gap:5px;align-items:center;font-size:10px;color:var(--muted)}.card-tools{gap:3px}.small-icon{display:grid;place-items:center;background:transparent;border:0;color:var(--faint);padding:5px;border-radius:5px}.small-icon:hover{background:var(--surface);color:var(--text)}.star-btn.active{color:#d1ab5a}.flagged{color:#cc8276}.delete:hover{color:#d67c70}.completed h3{color:var(--muted)}.move-wrap{position:relative}.move-menu{position:absolute;right:0;top:28px;width:115px;background:var(--card);padding:5px;border:1px solid var(--line);border-radius:9px;z-index:10;box-shadow:var(--shadow)}.move-menu button{display:block;width:100%;padding:8px;border:0;border-radius:5px;background:none;color:var(--text);text-align:left}.move-menu button:hover{background:var(--surface)}.move-menu button:disabled{opacity:.35;cursor:default}</style>
